{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Carbamazepine epoxide, the closest structural analogue with the same dibenzazepine carboxamide core, has an absolute oral bioavailability of 60% (95% CI 49–75%) in healthy subjects, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Cumulative urinary recovery in the valpromide interaction study indicated that carbamazepine epoxide bioavailability was at least 57% in humans, supporting high oral absorption for this close analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Oxcarbazepine, a closely related dibenzazepine carboxamide, has almost complete oral bioavailability of 95% in humans, supporting high F for the same scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Licarbazepine, the reduced metabolite of oxcarbazepine, has a mean absolute bioavailability of 89% after oral dosing in healthy adults, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Eslicarbazepine, another close analogue, has approximately 94% oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "PEMA, a smaller carboxamide-containing anticonvulsant analogue, has an absolute bioavailability of 91 ± 4.4% in normal volunteers, supporting high oral bioavailability for this compound class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is carbamazepine, a dibenzazepine carboxamide. The closest analogue, carbamazepine epoxide, has measured absolute oral bioavailability of 60% (95% CI 49–75%), and related dibenzazepine carboxamides (oxcarbazepine, licarbazepine, eslicarbazepine) show near-complete oral bioavailability in humans. These direct human data strongly support F ≥ 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for carbamazepine itself is present in the supplied records; the prediction relies on close structural analogues.",
    "The closest analogue, carbamazepine epoxide, is a metabolite and its absorption may differ somewhat from the parent drug."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

